/* v61: Chỉ số triển khai theo khu trên điện thoại */
.kt-dt { display:grid; gap:10px; }
.kt-the { border:1px solid var(--vien); border-radius:14px; padding:12px; display:grid; gap:10px; background:#fff; }
.kt-dau { display:flex; align-items:center; gap:10px; }
.kt-ic { flex:none; width:34px; height:34px; border-radius:10px; display:grid; place-items:center; background:var(--xanh2); color:var(--xanh); } .kt-ic .ic svg { width:18px; height:18px; }
.kt-ten { flex:1; min-width:0; font-size:16px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.kt-diem { flex:none; display:flex; align-items:baseline; gap:3px; } .kt-diem b { font-size:26px; line-height:1; } .kt-diem small { font-size:12px; font-weight:700; color:var(--xam); }
.kt-dong { display:grid; gap:4px; }
.kt-nhan { display:flex; align-items:baseline; gap:8px; font-size:13.5px; } .kt-nhan span { flex:1; color:var(--xam); font-weight:600; } .kt-nhan b { font-size:14.5px; } .kt-nhan em { font-style:normal; font-size:12px; color:var(--xam); min-width:72px; text-align:right; }
.kt-thanh { height:8px; border-radius:5px; background:#eef2f7; overflow:hidden; } .kt-thanh i { display:block; height:100%; border-radius:5px; }
  { // v61: điện thoại – mỗi khu 1 thẻ (điểm to + 3 thanh tiến độ); máy tính giữ bảng
    const bangKhu = `<div class="cuon"><table class="tk-bang"><tr><th>Khu</th><th class="so">Điểm</th><th class="so">Thu tiền</th><th class="so">Hộ dùng website</th><th class="so">Phiếu đã xử lý</th></tr>`
        <td class="so">${x.phieu ? pt(x.phieuXong, x.phieu) + '%<br><span class="nho">' + so(x.phieuXong) + '/' + so(x.phieu) + '</span>' : '–'}</td></tr>`).join('') + '</table></div>';
    const dongK = (ten, da, tong) => { const p = tong ? pt(da, tong) : null; return `<div class="kt-dong"><div class="kt-nhan"><span>${ten}</span><b>${p === null ? '–' : p + '%'}</b><em>${tong ? so(da) + '/' + so(tong) : 'chưa có'}</em></div><div class="kt-thanh"><i style="width:${p || 0}%;background:${mau(p || 0)}"></i></div></div>`; };
    const theKhu = '<div class="kt-dt">' + r.khu.map(x => `<div class="kt-the"><div class="kt-dau"><span class="kt-ic">${ic('pin')}</span><b class="kt-ten">${esc(x.khu)}</b><span class="kt-diem" style="color:${mau(x.diem)}"><b>${x.diem}</b><small>điểm</small></span></div>`
      + dongK('Thu tiền', x.da, x.phai) + dongK('Hộ dùng website', x.dungWeb, x.ho) + dongK('Phiếu đã xử lý', x.phieuXong, x.phieu) + '</div>').join('') + '</div>';
    h += `<div class="the"><h3>${ic('building')} Chỉ số triển khai theo khu</h3>${hep600() ? theKhu : bangKhu}</div>`;
  }
